const CATEGORIES = ["All", ...new Set(GRANTS.map(g => g.category))];
let savedIds = new Set();
let activeCategory = "All";
let searchTerm = "";

async function loadSaved(){
  try{
    const res = await window.storage.get('saved-grant-ids', false);
    if(res && res.value) savedIds = new Set(JSON.parse(res.value));
  }catch(e){ /* no saved entries yet */ }
}
async function persistSaved(){
  try{ await window.storage.set('saved-grant-ids', JSON.stringify([...savedIds]), false); }
  catch(e){ console.error('Could not save bookmark', e); }
}

function statusLabel(s){
  return {open:"Open", recurring:"Recurring", closed:"Cycle Closed", discontinued:"Discontinued"}[s] || s;
}

function renderTabs(){
  const row = document.getElementById('tabRow');
  row.innerHTML = '';
  CATEGORIES.forEach(cat => {
    const btn = document.createElement('button');
    btn.className = 'tab' + (cat === activeCategory ? ' active' : '');
    btn.textContent = cat === "All" ? "All Entries" : cat;
    btn.onclick = () => { activeCategory = cat; renderTabs(); renderGrid(); };
    row.appendChild(btn);
  });
}

function matchesSearch(g, term){
  if(!term) return true;
  const hay = (g.name + ' ' + g.agency + ' ' + g.desc + ' ' + g.eligibility.join(' ')).toLowerCase();
  return hay.includes(term.toLowerCase());
}

function renderGrid(){
  const grid = document.getElementById('grid');
  const empty = document.getElementById('emptyMsg');
  grid.innerHTML = '';
  const filtered = GRANTS.filter(g =>
    (activeCategory === "All" || g.category === activeCategory) && matchesSearch(g, searchTerm)
  );
  document.getElementById('countLabel').textContent = `${filtered.length} of ${GRANTS.length} entries indexed`;
  empty.style.display = filtered.length ? 'none' : 'block';

  filtered.forEach(g => {
    const card = document.createElement('div');
    card.className = 'card';
    card.tabIndex = 0;
    card.setAttribute('role','button');
    card.setAttribute('aria-label', 'Open record: ' + g.name);
    card.innerHTML = `
      <div class="card-tab">${g.category}</div>
      <div class="stamp ${g.status}">${statusLabel(g.status)}</div>
      <h3>${g.name}</h3>
      <div class="agency">${g.agency}</div>
      <p class="desc">${g.desc}</p>
      <div class="meta-row"><span>${g.amount.split('(')[0].trim().slice(0,28)}</span><span>${g.id}</span></div>
      <button class="save-btn ${savedIds.has(g.id) ? 'saved' : ''}" aria-label="Bookmark this grant" data-id="${g.id}">${savedIds.has(g.id) ? '★' : '☆'}</button>
    `;
    card.addEventListener('click', (e) => {
      if(e.target.classList.contains('save-btn')) return;
      openRecord(g);
    });
    card.addEventListener('keypress', (e) => { if(e.key === 'Enter') openRecord(g); });
    card.querySelector('.save-btn').addEventListener('click', async (e) => {
      e.stopPropagation();
      const id = e.target.getAttribute('data-id');
      if(savedIds.has(id)){ savedIds.delete(id); } else { savedIds.add(id); }
      await persistSaved();
      renderGrid();
    });
    grid.appendChild(card);
  });
}

function openRecord(g){
  const overlay = document.getElementById('overlay');
  const content = document.getElementById('recordContent');
  content.innerHTML = `
    <button class="close" aria-label="Close">×</button>
    <div class="rec-id">${g.id} — ${g.category}</div>
    <h2>${g.name}</h2>
    <div class="agency-line">${g.agency}</div>
    <p>${g.desc}</p>
    <h4>Eligibility</h4>
    <ul>${g.eligibility.map(e => `<li>${e}</li>`).join('')}</ul>
    <h4>Award Amount</h4>
    <p>${g.amount}</p>
    <h4>Deadline / Cycle</h4>
    <p>${g.deadline}</p>
    <h4>How to Apply</h4>
    <p>${g.applyVia}</p>
    ${g.notes ? `<h4>Notes</h4><p>${g.notes}</p>` : ''}
    <a class="src" href="${g.source}" target="_blank" rel="noopener">View source →</a>
  `;
  content.querySelector('.close').onclick = closeRecord;
  overlay.classList.add('show');
}
function closeRecord(){ document.getElementById('overlay').classList.remove('show'); }
document.getElementById('overlay').addEventListener('click', (e) => {
  if(e.target.id === 'overlay') closeRecord();
});
