const CATEGORIES = ["All", ...new Set(GRANTS.map(g => g.category))];
let savedIds = new Set();
let activeCategory = "All";
let searchTerm = "";
let mode = "curated"; // 'curated' | 'live'

// ---- Live grants.gov API layer ----
const GRANTS_API = "https://api.grants.gov/v1/api/search2";
const GRANTS_DETAIL_API = "https://api.grants.gov/v1/api/fetchOpportunity";
const LIVE_FILTERS = [
  { label:"All Open", params:{} },
  { label:"Faith-Based & Nonprofit", params:{ keyword:"faith-based nonprofit" } },
  { label:"Workforce & Job Training", params:{ fundingCategories:"ELT" } },
  { label:"Community Development", params:{ fundingCategories:"CD" } },
  { label:"Rural Development", params:{ fundingCategories:"RD" } },
  { label:"Housing", params:{ fundingCategories:"HO" } },
  { label:"Arts & Humanities", params:{ fundingCategories:"HU" } },
  { label:"Health & Human Services", params:{ fundingCategories:"HL" } }
];
const ELIGIBILITY_CODES = [
  { v:"", l:"Any eligibility" },
  { v:"12", l:"501(c)(3) nonprofits" },
  { v:"13", l:"Nonprofits w/o 501(c)(3)" },
  { v:"07", l:"Native American tribal govts" },
  { v:"25", l:"Others (see listing)" },
  { v:"99", l:"Unrestricted" },
  { v:"00", l:"State governments" },
  { v:"23", l:"Small businesses" }
];
let liveFilterIdx = 0;
let liveEligibility = "";
let liveIncludeClosed = false;
let liveStartRecord = 0;
const LIVE_ROWS = 20;
let liveHits = [];
let liveHitCount = 0;
let liveLoading = false;

async function liveSearch(reset){
  if(reset){ liveStartRecord = 0; liveHits = []; }
  liveLoading = true;
  renderGrid();
  const body = Object.assign(
    { rows: LIVE_ROWS, startRecordNum: liveStartRecord,
      oppStatuses: liveIncludeClosed ? "posted|forecasted|closed|archived" : "posted|forecasted" },
    LIVE_FILTERS[liveFilterIdx].params
  );
  if(searchTerm) body.keyword = searchTerm;
  if(liveEligibility) body.eligibilities = liveEligibility;
  try{
    const res = await fetch(GRANTS_API, {
      method:"POST",
      headers:{ "Content-Type":"application/json" },
      body: JSON.stringify(body)
    });
    const json = await res.json();
    const data = json.data || {};
    liveHitCount = data.hitCount || 0;
    liveHits = liveHits.concat(data.oppHits || []);
  }catch(e){
    console.error("Live search failed", e);
    liveHitCount = liveHits.length;
  }
  liveLoading = false;
  renderGrid();
}

function statusFromOppStatus(s){
  return { posted:"open", forecasted:"recurring", closed:"closed", archived:"discontinued" }[s] || s;
}
function fmtDate(d){ return d ? d : "—"; }

async function openLiveRecord(hit){
  const overlay = document.getElementById('overlay');
  const content = document.getElementById('recordContent');
  content.innerHTML = `<button class="close" aria-label="Close">×</button><p style="font-family:'IBM Plex Mono',monospace;font-size:0.8rem;">Pulling record from grants.gov…</p>`;
  content.querySelector('.close').onclick = closeRecord;
  overlay.classList.add('show');
  try{
    const res = await fetch(GRANTS_DETAIL_API, {
      method:"POST",
      headers:{ "Content-Type":"application/json" },
      body: JSON.stringify({ opportunityId: parseInt(hit.id, 10) })
    });
    const json = await res.json();
    const d = (json.data || {});
    const syn = d.synopsis || {};
    const tmp = document.createElement('div');
    tmp.innerHTML = syn.synopsisDesc || "No synopsis provided.";
    const descText = tmp.textContent || tmp.innerText || "";
    const elig = (syn.applicantTypes || []).map(a => `<li>${a.description}</li>`).join('') || '<li>See source listing</li>';
    const award = (syn.awardFloorFormatted || syn.awardCeilingFormatted)
      ? `$${syn.awardFloorFormatted || '0'} – $${syn.awardCeilingFormatted || '—'} (${syn.numberOfAwards || '?'} awards anticipated)`
      : "Not specified in listing";
    content.innerHTML = `
      <button class="close" aria-label="Close">×</button>
      <div class="rec-id">${d.opportunityNumber || hit.number || ''} — Live from grants.gov</div>
      <h2>${d.opportunityTitle || hit.title}</h2>
      <div class="agency-line">${(syn.topAgencyDetails && syn.topAgencyDetails.agencyName) || hit.agency || d.owningAgencyCode}</div>
      <p>${descText.slice(0, 900)}${descText.length > 900 ? '…' : ''}</p>
      <h4>Eligibility</h4>
      <ul>${elig}</ul>
      <h4>Award Amount</h4>
      <p>${award}</p>
      <h4>Posted / Deadline</h4>
      <p>Posted ${fmtDate(syn.postingDate)} — Response due ${fmtDate(syn.responseDate)}</p>
      <a class="src" href="https://www.grants.gov/search-results-detail/${hit.id}" target="_blank" rel="noopener">View live on grants.gov →</a>
    `;
    content.querySelector('.close').onclick = closeRecord;
  }catch(e){
    content.innerHTML = `<button class="close" aria-label="Close">×</button><p>Couldn't load full record. <a class="src" href="https://www.grants.gov/search-results-detail/${hit.id}" target="_blank">View it directly on grants.gov →</a></p>`;
    content.querySelector('.close').onclick = closeRecord;
  }
}

// ---- Storage ----
