  try{
    const res = await window.storage.get('saved-grant-ids', false);
    if(res && res.value) savedIds = new Set(JSON.parse(res.value));
  }catch(e){ /* no saved entries yet */ }
}
async function persistSaved(){
  try{ await window.storage.set('saved-grant-ids', JSON.stringify([...savedIds]), false); }
  catch(e){ console.error('Could not save bookmark', e); }
}

function statusLabel(s){
  return {open:"Open", recurring:"Recurring", closed:"Cycle Closed", discontinued:"Discontinued"}[s] || s;
}

// ---- Mode / tab / filter chrome ----
function renderModeChrome(){
  document.getElementById('modeCuratedBtn').classList.toggle('active', mode === 'curated');
  document.getElementById('modeLiveBtn').classList.toggle('active', mode === 'live');
  document.getElementById('liveFilters').style.display = mode === 'live' ? 'flex' : 'none';
  document.getElementById('tabRow').style.display = mode === 'curated' ? 'flex' : 'none';
  document.getElementById('loadMoreWrap').style.display = mode === 'live' ? 'block' : 'none';

  if(mode === 'live'){
    const wrap = document.getElementById('liveFilters');
    wrap.innerHTML = '';
    const catRow = document.createElement('div');
    catRow.style.cssText = "display:flex;flex-wrap:wrap;gap:0.4rem;justify-content:center;width:100%;margin-bottom:0.5rem;";
    LIVE_FILTERS.forEach((f, i) => {
      const b = document.createElement('button');
      b.className = 'tab' + (i === liveFilterIdx ? ' active' : '');
      b.textContent = f.label;
      b.onclick = () => { liveFilterIdx = i; liveSearch(true); };
      catRow.appendChild(b);
    });
    wrap.appendChild(catRow);

    const eligSel = document.createElement('select');
    ELIGIBILITY_CODES.forEach(o => {
      const opt = document.createElement('option');
      opt.value = o.v; opt.textContent = o.l;
      if(o.v === liveEligibility) opt.selected = true;
      eligSel.appendChild(opt);
    });
    eligSel.onchange = (e) => { liveEligibility = e.target.value; liveSearch(true); };
    wrap.appendChild(eligSel);

    const label = document.createElement('label');
    const cb = document.createElement('input');
    cb.type = 'checkbox'; cb.checked = liveIncludeClosed;
    cb.onchange = (e) => { liveIncludeClosed = e.target.checked; liveSearch(true); };
