    wrap.appendChild(label);
  }
}

function renderTabs(){
  const row = document.getElementById('tabRow');
  row.innerHTML = '';
  CATEGORIES.forEach(cat => {
    const btn = document.createElement('button');
    btn.className = 'tab' + (cat === activeCategory ? ' active' : '');
    btn.textContent = cat === "All" ? "All Entries" : cat;
    btn.onclick = () => { activeCategory = cat; renderTabs(); renderGrid(); };
    row.appendChild(btn);
  });
}

function matchesSearch(g, term){
  if(!term) return true;
  const hay = (g.name + ' ' + g.agency + ' ' + g.desc + ' ' + g.eligibility.join(' ')).toLowerCase();
  return hay.includes(term.toLowerCase());
}

function renderGrid(){
  const grid = document.getElementById('grid');
  const empty = document.getElementById('emptyMsg');
  const countLabel = document.getElementById('countLabel');
  const loadMoreWrap = document.getElementById('loadMoreWrap');

  if(mode === 'curated'){
    grid.innerHTML = '';
    const filtered = GRANTS.filter(g =>
      (activeCategory === "All" || g.category === activeCategory) && matchesSearch(g, searchTerm)
    );
    countLabel.textContent = `${filtered.length} of ${GRANTS.length} hand-verified entries`;
    empty.style.display = filtered.length ? 'none' : 'block';
    loadMoreWrap.style.display = 'none';

    filtered.forEach(g => {
      const card = document.createElement('div');
      card.className = 'card';
      card.tabIndex = 0;
      card.setAttribute('role','button');
      card.setAttribute('aria-label', 'Open record: ' + g.name);
      card.innerHTML = `
        <div class="card-tab">${g.category}</div>
        <div class="stamp ${g.status}">${statusLabel(g.status)}</div>
        <h3>${g.name}</h3>
        <div class="agency">${g.agency}</div>
        <p class="desc">${g.desc}</p>
        <div class="meta-row"><span>${g.amount.split('(')[0].trim().slice(0,28)}</span><span>${g.id}</span></div>
        <button class="save-btn ${savedIds.has(g.id) ? 'saved' : ''}" aria-label="Bookmark this grant" data-id="${g.id}">${savedIds.has(g.id) ? '★' : '☆'}</button>
      `;
      card.addEventListener('click', (e) => {
        if(e.target.classList.contains('save-btn')) return;
        openRecord(g);
      });
      card.addEventListener('keypress', (e) => { if(e.key === 'Enter') openRecord(g); });
      card.querySelector('.save-btn').addEventListener('click', async (e) => {
        e.stopPropagation();
        const id = e.target.getAttribute('data-id');
        if(savedIds.has(id)){ savedIds.delete(id); } else { savedIds.add(id); }
        await persistSaved();
        renderGrid();
      });
      grid.appendChild(card);
    });
  } else {
    // live mode
    grid.innerHTML = '';
    countLabel.textContent = liveLoading && liveHits.length === 0
      ? 'Querying grants.gov…'
      : `${liveHitCount.toLocaleString()} currently matching opportunities — showing ${liveHits.length}`;
    empty.style.display = (!liveLoading && liveHits.length === 0) ? 'block' : 'none';
    loadMoreWrap.style.display = liveHits.length < liveHitCount ? 'block' : 'none';

    liveHits.forEach(hit => {
      const st = statusFromOppStatus(hit.oppStatus);
      const bookmarkKey = 'live:' + hit.id;
      const card = document.createElement('div');
      card.className = 'card';
      card.tabIndex = 0;
      card.setAttribute('role','button');
      card.innerHTML = `
        <div class="card-tab">${hit.agencyCode || 'FEDERAL'}</div>
        <div class="stamp ${st}">${hit.oppStatus}</div>
        <h3>${hit.title}</h3>
        <div class="agency">${hit.agency}</div>
        <p class="desc">Opportunity #${hit.number} · Opens ${fmtDate(hit.openDate)}${hit.closeDate ? ' · Closes ' + hit.closeDate : ''}</p>
        <div class="meta-row"><span>${(hit.cfdaList || []).join(', ') || 'No CFDA'}</span><span>${hit.id}</span></div>
        <button class="save-btn ${savedIds.has(bookmarkKey) ? 'saved' : ''}" aria-label="Bookmark this grant" data-id="${bookmarkKey}">${savedIds.has(bookmarkKey) ? '★' : '☆'}</button>
      `;
      card.addEventListener('click', (e) => {
        if(e.target.classList.contains('save-btn')) return;
        openLiveRecord(hit);
      });
      card.querySelector('.save-btn').addEventListener('click', async (e) => {
        e.stopPropagation();
        const id = e.target.getAttribute('data-id');
        if(savedIds.has(id)){ savedIds.delete(id); } else { savedIds.add(id); }
        await persistSaved();
        renderGrid();
      });
      grid.appendChild(card);
    });
  }
}

