function closeRecord(){ document.getElementById('overlay').classList.remove('show'); }
document.getElementById('overlay').addEventListener('click', (e) => {
  if(e.target.id === 'overlay') closeRecord();
});
document.addEventListener('keydown', (e) => { if(e.key === 'Escape') closeRecord(); });

let searchDebounce;
document.getElementById('searchInput').addEventListener('input', (e) => {
  searchTerm = e.target.value;
  if(mode === 'curated'){ renderGrid(); }
  else{
    clearTimeout(searchDebounce);
    searchDebounce = setTimeout(() => liveSearch(true), 400);
  }
});

document.getElementById('modeCuratedBtn').onclick = () => {
  mode = 'curated'; searchTerm = ''; document.getElementById('searchInput').value = '';
  renderModeChrome(); renderTabs(); renderGrid();
};
document.getElementById('modeLiveBtn').onclick = () => {
  mode = 'live'; searchTerm = ''; document.getElementById('searchInput').value = '';
  renderModeChrome();
  if(liveHits.length === 0) liveSearch(true); else renderGrid();
};
document.getElementById('loadMoreBtn').onclick = () => {
  liveStartRecord += LIVE_ROWS;
  liveSearch(false);
};

